int main(int argc,char** argv){QCoreApplication application(argc,argv);try{if(argc==5&&std::string_view(argv[1])=="--interrupted-panel-child")return interruptedChild(argv[2],argv[3],QString::fromUtf8(argv[4]));if(argc!=5)return 64;Path source=argv[1],parent=argv[2],build=argv[3],sys=argv[4];underlay::privateDirectory(parent);QTemporaryDir owned(QString::fromStdString((parent/"interrupted-panel-XXXXXX").string()));CHECK(owned.isValid());owned.setAutoRemove(false);Path data=owned.path().toStdString();std::cout<<"INTERRUPTED_PANEL_DATA "<<data<<'\n'<<std::flush;auto app=stage(source,data/"stage",build,sys);unsigned cases=0;
 for(const auto& scenario:{QString("notes-pen"),QString("notes-eraser"),QString("tom-pen"),QString("tom-eraser")}){bool tom=scenario.startsWith("tom-"),erase=scenario.endsWith("eraser");auto root=data/scenario.toStdString();underlay::privateDirectory(root/"inbox");std::filesystem::copy_file(source/"fixtures/library/authored-three-pages.pdf",root/"inbox/authored.pdf");std::atomic<bool> stop{false};reader::syncLibrary(app,root,stop);auto book=library::documents(root)[0];auto features=product::featureDirectory(root,book),docroot=library::documentRoot(root,book.id);QProcess child;child.setProcessChannelMode(QProcess::ForwardedErrorChannel);child.setProgram(QString::fromStdString((sys/"usr/lib/ld-linux-aarch64.so.1").string()));child.setArguments({"--library-path",QString::fromStdString((sys/"usr/lib").string()),QString::fromUtf8(argv[0]),"--interrupted-panel-child",QString::fromStdString(app.string()),QString::fromStdString(root.string()),scenario});child.start();CHECK(child.waitForStarted(5000)&&child.waitForFinished(45000));auto out=child.readAllStandardOutput(),err=child.readAllStandardError();if(child.exitCode()!=78||!out.contains("INTERRUPTED_PANEL_QUEUE_AND_PARTIAL_DURABLE_UNCLEAN")){std::cerr<<out.constData()<<err.constData();CHECK(false);}CHECK(child.exitStatus()==QProcess::NormalExit);auto expected=readJson(root/"panel-interruption-expectation.json");CHECK(expected["scenario"]==scenario&&reader::readViewResume(docroot,3,{}).page==1&&!reader::readViewResume(docroot,3,{}).clean);preserve(root,features,expected,tom,erase);auto directory=tom?root/"tom-interrupted":features/"interrupted-notes";auto paths=archives(directory);QByteArray archived;if(erase)archived=underlay::readBounded(paths[0],1024*1024);
  {ux::Shell shell(app,root,true,false,false);Canvas canvas(shell);CHECK(shell.choose(0));canvas.ready();documentReady(shell,canvas);CHECK(shell.page()==1&&inkHash(shell)==expected["sourceInk"].toString().toLatin1()&&!reader::readViewResume(docroot,3,{}).clean);if(tom){openTom(shell,canvas);auto view=shell.tomPanel()->view();CHECK(view.thread==expected["conversation"].toString()&&view.turn==expected["turn"].toString()&&view.context==expected["uiContext"].toObject()&&view.question=="Q"&&!view.consent&&!view.active&&!view.configured&&!view.helperBusy);CHECK(view.handwriting==privateDraft(root,view.thread,view.turn)["handwriting"].toArray());tap(shell,canvas,1100,ib::tom::SheetTop+ib::tom::HeaderHeight+20);tomReady(shell,canvas);} /* a blank tap inside the sheet (the empty quote row of a page question) */
   else{openNotes(shell,canvas);tap(shell,canvas,300,520);notesReady(shell,canvas,true);auto view=shell.notesPanel()->view();CHECK(view.note["id"]==expected["note"]&&view.note["strokes"]==note(features,expected["note"].toString())["strokes"]);}
   preserve(root,features,expected,tom,erase);CHECK(shell.unsaved()==0&&!shell.failed()&&inkHash(shell)==expected["sourceInk"].toString().toLatin1());CHECK(archives(directory)==paths);if(erase)CHECK(underlay::readBounded(paths[0],1024*1024)==archived);CHECK(!std::filesystem::exists(root/"helper.log"));CHECK(shell.finish(5000)&&shell.unsaved()==0);}
  CHECK(reader::readViewResume(docroot,3,{}).clean);++cases;std::cout<<"PASS "<<scenario.toStdString()<<" completed_queued_then_partial=true terminal_display_cancel=true child_destructor=78 exact_fresh_reopen=true actual_samples_only=true\n"<<std::flush;
 }
 CHECK(owned.remove());std::cout<<"INTERRUPTED_PANEL_ROUTE_PASS cases="<<cases<<" actual_shell_display=true queued_completed_work_drained=true notes_style_scroll_geometry=true private_tom_question_context_ink=true partial_pen_reopen=true erasers_archived_unapplied=true logical_unsaved_unclean_retained=true synthetic_partial_release=NONE vendor_calls=0 provider_calls=NONE raw_input=NONE physical=NOT_RUN\n";return 0;
 }catch(const std::exception& e){std::cerr<<"INTERRUPTED_PANEL_ROUTE_FAIL "<<e.what()<<'\n';return 1;}}
